import { createHash } from 'node:crypto';
import { readFileSync, statSync } from 'node:fs';
import { unzipSync, zipSync } from 'fflate';
import { describe, expect, it } from 'vitest';
import { WorkbookOpenError } from '@ooxml/errors';
import { openWorkbook } from '@ooxml/open';
import { parseXml } from '@ooxml/xml';
import { buildXlsx } from './helpers/build-xlsx';

/**
 * M6 lane 1 — hostile input and Tier C (file-compat.md §5, §8, §9).
 *
 *   npx vitest run tests/m6-hostile.test.ts
 *
 * F18-F21 are committed fixtures under `fixtures/compat/`, regenerated by
 * `scripts/fixtures/groups/hostile.mjs`. Each is rejected with the §5 message,
 * imports nothing and leaves the file untouched. The zip-bomb cases prove the
 * caps fire on declared sizes before decompression: a package whose central
 * directory claims a multi-gigabyte part is rejected in the header check, so
 * the allocation never happens (a regression fails on the error type, not only
 * on timing).
 */

const ENCRYPTED_MESSAGE =
  'This workbook is encrypted or password-protected. calcplus cannot open it.';
const CORRUPT_MESSAGE = 'This file is damaged or is not a valid workbook.';
const TOO_LARGE_MESSAGE = 'This workbook is too large or unusually compressed to open safely.';
const STRICT_MESSAGE = 'This workbook uses an OOXML variant calcplus does not support yet.';

const SPREADSHEET_NS = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main';
const FIXED_MTIME = new Date('1980-01-01T00:00:00Z');
const FIXTURE_DIR = new URL('../fixtures/compat/', import.meta.url);

function fixturePath(name: string): URL {
  return new URL(name, FIXTURE_DIR);
}

function fixtureBytes(name: string): Uint8Array {
  return new Uint8Array(readFileSync(fixturePath(name)));
}

interface FixtureSnapshot {
  readonly bytes: Uint8Array;
  readonly digest: string;
  readonly mtimeMs: number;
}

function snapshot(name: string): FixtureSnapshot {
  const path = fixturePath(name);
  const bytes = new Uint8Array(readFileSync(path));
  return {
    bytes,
    digest: createHash('sha256').update(bytes).digest('hex'),
    mtimeMs: statSync(path).mtimeMs,
  };
}

function expectOpenError(run: () => unknown, code: string, message: string): void {
  let caught: unknown;
  try {
    run();
  } catch (error) {
    caught = error;
  }
  expect(caught, 'expected the input to be rejected').toBeInstanceOf(WorkbookOpenError);
  expect((caught as WorkbookOpenError).code).toBe(code);
  expect((caught as WorkbookOpenError).message).toBe(message);
}

const HOSTILE_FIXTURES = [
  { id: 'F18', name: 'encrypted.xlsx', code: 'encrypted', message: ENCRYPTED_MESSAGE },
  { id: 'F19', name: 'corrupt.xlsx', code: 'corrupt', message: CORRUPT_MESSAGE },
  { id: 'F20', name: 'zip-bomb.xlsx', code: 'too-large', message: TOO_LARGE_MESSAGE },
  { id: 'F21', name: 'strict-ooxml.xlsx', code: 'strict-ooxml', message: STRICT_MESSAGE },
] as const;

describe('Tier C fixture corpus (F18-F21)', () => {
  for (const fixture of HOSTILE_FIXTURES) {
    it(`${fixture.id} ${fixture.name}: rejected with the §5 message, no import, file untouched`, () => {
      const before = snapshot(fixture.name);
      const input = before.bytes.slice();

      expectOpenError(() => openWorkbook(input, fixture.name), fixture.code, fixture.message);

      // The buffer handed to the reader is not mutated.
      expect(input).toEqual(before.bytes);
      // The file on disk is not written or replaced.
      const after = snapshot(fixture.name);
      expect(after.digest).toBe(before.digest);
      expect(after.mtimeMs).toBe(before.mtimeMs);
    });
  }

  it('F18 is a Compound File Binary container, not a ZIP', () => {
    const bytes = fixtureBytes('encrypted.xlsx');
    expect([...bytes.subarray(0, 8)]).toEqual([0xd0, 0xcf, 0x11, 0xe0, 0xa1, 0xb1, 0x1a, 0xe1]);
    expect(bytes[0]).not.toBe(0x50);
  });

  it('F19 starts as a ZIP and dies in the central-directory parse, with no partial package', () => {
    const bytes = fixtureBytes('corrupt.xlsx');
    expect([...bytes.subarray(0, 4)]).toEqual([0x50, 0x4b, 0x03, 0x04]);
    expectOpenError(() => openWorkbook(bytes), 'corrupt', CORRUPT_MESSAGE);
  });

  it('F20 declares one entry above the compression-ratio cap', () => {
    const bytes = fixtureBytes('zip-bomb.xlsx');
    expect(bytes.byteLength).toBeLessThan(64 * 1024);
    const declared = declaredEntry(bytes, 'xl/media/bomb.bin');
    expect(declared.uncompressedSize).toBe(16 * 1024 * 1024);
    // §8: the ratio cap is 200:1.
    expect(declared.uncompressedSize / declared.compressedSize).toBeGreaterThan(200);
  });

  it('F21 is Strict OOXML throughout, not a damaged package', () => {
    const parts = unzipSync(fixtureBytes('strict-ooxml.xlsx'));
    expect(new TextDecoder().decode(parts['xl/workbook.xml']!)).toContain(
      'http://purl.oclc.org/ooxml/spreadsheetml/main',
    );
    expect(new TextDecoder().decode(parts['xl/worksheets/sheet1.xml']!)).toContain(
      'http://purl.oclc.org/ooxml/spreadsheetml/main',
    );
  });

  it('leaves a normal workbook openable after every rejection', () => {
    const good = fixtureBytes('identity-minimal.xlsx');
    for (const fixture of HOSTILE_FIXTURES) {
      expect(() => openWorkbook(fixtureBytes(fixture.name))).toThrow(WorkbookOpenError);
      const opened = openWorkbook(good);
      expect(opened.workbook.sheets[0]!.name).toBe('Sheet1');
      expect(opened.workbook.sheets[0]!.cells.size).toBe(3);
    }
  });
});

interface DeclaredEntry {
  readonly name: string;
  readonly compressedSize: number;
  readonly uncompressedSize: number;
}

/** Locate one central-directory record without decompressing anything. */
function centralDirectoryRecordOffset(bytes: Uint8Array, wanted: string): number {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  let eocd = -1;
  for (let index = bytes.byteLength - 22; index >= 0; index -= 1) {
    if (view.getUint32(index, true) === 0x06054b50) {
      eocd = index;
      break;
    }
  }
  if (eocd < 0) throw new Error('No end-of-central-directory record');

  const count = view.getUint16(eocd + 10, true);
  const decoder = new TextDecoder('utf-8');
  let offset = view.getUint32(eocd + 16, true);
  for (let index = 0; index < count; index += 1) {
    const nameLength = view.getUint16(offset + 28, true);
    const name = decoder.decode(bytes.subarray(offset + 46, offset + 46 + nameLength));
    if (name === wanted) return offset;
    offset +=
      46 + nameLength + view.getUint16(offset + 30, true) + view.getUint16(offset + 32, true);
  }
  throw new Error(`Central directory has no entry named ${wanted}`);
}

/** Read a fixture's declared entry sizes without decompressing anything. */
function declaredEntry(bytes: Uint8Array, wanted: string): DeclaredEntry {
  const offset = centralDirectoryRecordOffset(bytes, wanted);
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  return {
    name: wanted,
    compressedSize: view.getUint32(offset + 20, true),
    uncompressedSize: view.getUint32(offset + 24, true),
  };
}

/**
 * Rewrite one central-directory record's declared sizes. The result is a valid
 * package with a lying directory: the shape a hostile file uses to make a
 * reader allocate before it validates.
 */
function rewriteDeclaredSizes(
  bytes: Uint8Array,
  wanted: string,
  sizes: { compressedSize?: number; uncompressedSize?: number },
): Uint8Array {
  const copy = bytes.slice();
  const offset = centralDirectoryRecordOffset(copy, wanted);
  const view = new DataView(copy.buffer, copy.byteOffset, copy.byteLength);
  if (sizes.compressedSize !== undefined) {
    view.setUint32(offset + 20, sizes.compressedSize, true);
  }
  if (sizes.uncompressedSize !== undefined) {
    view.setUint32(offset + 24, sizes.uncompressedSize, true);
  }
  return copy;
}

/**
 * Overwrite one entry's compressed payload with bytes that cannot inflate,
 * leaving the central directory intact. Used to prove the caps are applied
 * before decompression: the same bytes fail as a corrupt package when the
 * declared sizes stay under the caps.
 */
function corruptLocalData(bytes: Uint8Array, wanted: string): Uint8Array {
  const copy = bytes.slice();
  const view = new DataView(copy.buffer, copy.byteOffset, copy.byteLength);
  const decoder = new TextDecoder('utf-8');
  let offset = 0;
  while (offset + 30 <= copy.byteLength && view.getUint32(offset, true) === 0x04034b50) {
    const compressedSize = view.getUint32(offset + 18, true);
    const nameLength = view.getUint16(offset + 26, true);
    const extraLength = view.getUint16(offset + 28, true);
    const name = decoder.decode(copy.subarray(offset + 30, offset + 30 + nameLength));
    const dataStart = offset + 30 + nameLength + extraLength;
    if (name === wanted) {
      copy.fill(0xff, dataStart, dataStart + compressedSize);
      return copy;
    }
    offset = dataStart + compressedSize;
  }
  throw new Error(`Local header for ${wanted} not found`);
}

/** Deterministic pseudo-random bytes: deflate cannot compress them. */
function incompressibleBytes(length: number): Uint8Array<ArrayBuffer> {
  const bytes = new Uint8Array(length);
  let state = 0x9e3779b9;
  for (let index = 0; index < length; index += 1) {
    state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
    bytes[index] = state >>> 24;
  }
  return bytes;
}

const SIMPLE_SHEET = `<?xml version="1.0"?><worksheet xmlns="${SPREADSHEET_NS}"><sheetData><row r="1"><c r="A1"><v>1</v></c></row></sheetData></worksheet>`;

describe('package caps (file-compat.md §8)', () => {
  it('rejects a package above the 20,000-entry cap', () => {
    const entries: Record<string, Uint8Array> = {};
    for (let index = 0; index <= 20_000; index += 1) {
      entries[`xl/media/f${index}.bin`] = new Uint8Array(1);
    }
    const bytes = zipSync(entries, { level: 6, mtime: FIXED_MTIME });
    expectOpenError(() => openWorkbook(bytes), 'too-large', TOO_LARGE_MESSAGE);
  });

  it('rejects a declared total above the uncompressed cap before inflating', () => {
    let bytes = buildXlsx(SIMPLE_SHEET, {
      extraParts: { 'xl/media/a.bin': 'a', 'xl/media/b.bin': 'b' },
    });
    // Each entry is under the 200:1 ratio cap (800 MiB declared from 8 MiB
    // compressed is 100:1) but the two together exceed the 1.5 GiB total.
    for (const part of ['xl/media/a.bin', 'xl/media/b.bin']) {
      bytes = rewriteDeclaredSizes(bytes, part, {
        compressedSize: 8 * 1024 * 1024,
        uncompressedSize: 800 * 1024 * 1024,
      });
    }
    expectOpenError(() => openWorkbook(bytes), 'too-large', TOO_LARGE_MESSAGE);
  });

  it('rejects a lying directory that claims a multi-gigabyte part', () => {
    const bytes = rewriteDeclaredSizes(buildXlsx(SIMPLE_SHEET), 'xl/worksheets/sheet1.xml', {
      // 3.75 GiB, below the ZIP64 sentinel.
      uncompressedSize: 0xf0000000,
    });
    expectOpenError(() => openWorkbook(bytes), 'too-large', TOO_LARGE_MESSAGE);
  });

  it('applies the caps before decompressing the offending entry', () => {
    // Incompressible on purpose: the control must stay under the ratio cap
    // until the declared size is patched, so the rejection can only come from
    // the header check, not from the payload's compressibility.
    const parts = unzipSync(buildXlsx(SIMPLE_SHEET));
    parts['xl/media/early-abort.bin'] = incompressibleBytes(4096);
    const bomb = zipSync(parts, { level: 6, mtime: FIXED_MTIME });

    // Control: the payload is not a valid DEFLATE stream, so a reader that
    // inflates before checking caps reports damage.
    const damaged = corruptLocalData(bomb, 'xl/media/early-abort.bin');
    expectOpenError(() => openWorkbook(damaged), 'corrupt', CORRUPT_MESSAGE);

    // Same damaged payload, but the directory declares a ratio above the cap.
    // The only way to report the cap message is to check the header first.
    const notInflated = rewriteDeclaredSizes(damaged, 'xl/media/early-abort.bin', {
      uncompressedSize: 16 * 1024 * 1024,
    });
    expectOpenError(() => openWorkbook(notInflated), 'too-large', TOO_LARGE_MESSAGE);
  });

  it('rejects a single XML part above the 512 MB part cap', () => {
    const bytes = rewriteDeclaredSizes(buildXlsx(SIMPLE_SHEET), 'xl/worksheets/sheet1.xml', {
      // Ratio 100:1 and total 600 MB, so only the per-part cap can reject it.
      compressedSize: 6 * 1024 * 1024,
      uncompressedSize: 600 * 1024 * 1024,
    });
    expectOpenError(() => openWorkbook(bytes), 'too-large', TOO_LARGE_MESSAGE);
  });

  it('treats a zero compressed size with content as an unusable ratio', () => {
    const bytes = buildXlsx(SIMPLE_SHEET, { extraParts: { 'xl/media/zero.bin': 'z' } });
    const lying = rewriteDeclaredSizes(bytes, 'xl/media/zero.bin', {
      compressedSize: 0,
      uncompressedSize: 1024,
    });
    expectOpenError(() => openWorkbook(lying), 'too-large', TOO_LARGE_MESSAGE);
  });

  it('rejects entry names that escape the package', () => {
    const bytes = zipSync(
      {
        '[Content_Types].xml': new TextEncoder().encode('<Types/>'),
        '../escape.xml': new TextEncoder().encode('<a/>'),
      },
      { level: 6, mtime: FIXED_MTIME },
    );
    expectOpenError(
      () => openWorkbook(bytes),
      'corrupt',
      'Unsafe package entry name: ../escape.xml',
    );
  });

  it('rejects a ZIP-shaped file too short to hold a directory', () => {
    const bytes = new Uint8Array(8);
    bytes.set([0x50, 0x4b, 0x03, 0x04]);
    expectOpenError(() => openWorkbook(bytes), 'corrupt', CORRUPT_MESSAGE);
  });
});

describe('XXE-safe XML parsing (file-compat.md §8)', () => {
  const cases: readonly { readonly label: string; readonly document: string }[] = [
    {
      label: 'external entity declaration',
      document: `<?xml version="1.0"?><!DOCTYPE worksheet [<!ENTITY xxe SYSTEM "file:///etc/passwd">]><worksheet xmlns="${SPREADSHEET_NS}"><sheetData><row r="1"><c r="A1"><v>&xxe;</v></c></row></sheetData></worksheet>`,
    },
    {
      label: 'remote external entity',
      document: `<?xml version="1.0"?><!DOCTYPE worksheet [<!ENTITY xxe SYSTEM "http://169.254.169.254/latest/meta-data/">]><worksheet xmlns="${SPREADSHEET_NS}"><sheetData/></worksheet>`,
    },
    {
      label: 'internal entity expansion (billion laughs)',
      document: `<?xml version="1.0"?><!DOCTYPE worksheet [<!ENTITY a "aaaaaaaaaa"><!ENTITY b "&a;&a;&a;&a;&a;"><!ENTITY c "&b;&b;&b;&b;&b;">]><worksheet xmlns="${SPREADSHEET_NS}"><sheetData><row r="1"><c r="A1"><v>&c;</v></c></row></sheetData></worksheet>`,
    },
    {
      label: 'parameter entity',
      document: `<?xml version="1.0"?><!DOCTYPE worksheet [<!ENTITY % p SYSTEM "file:///etc/passwd">%p;]><worksheet xmlns="${SPREADSHEET_NS}"><sheetData/></worksheet>`,
    },
    {
      label: 'undefined entity reference without a DTD',
      document: `<?xml version="1.0"?><worksheet xmlns="${SPREADSHEET_NS}"><sheetData><row r="1"><c r="A1"><v>&xxe;</v></c></row></sheetData></worksheet>`,
    },
  ];

  for (const testCase of cases) {
    it(`rejects a ${testCase.label} as unsafe`, () => {
      let caught: unknown;
      try {
        openWorkbook(buildXlsx(testCase.document));
      } catch (error) {
        caught = error;
      }
      expect(caught).toBeInstanceOf(WorkbookOpenError);
      expect((caught as WorkbookOpenError).code).toBe('unsafe-xml');
      expect((caught as WorkbookOpenError).message).toMatch(/DTD or entity declaration/);
    });
  }

  it('rejects a DTD in a relationship part', () => {
    const bytes = buildXlsx(SIMPLE_SHEET, {
      extraParts: {
        'xl/_rels/sheet1.xml.rels':
          '<?xml version="1.0"?><!DOCTYPE Relationships [<!ENTITY x "y">]><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"/>',
      },
    });
    expectOpenError(
      () => openWorkbook(bytes),
      'unsafe-xml',
      'The workbook contains a DTD or entity declaration in xl/_rels/sheet1.xml.rels; calcplus rejects it for safety.',
    );
  });

  it('parses predefined and numeric references and never expands anything else', () => {
    const text: string[] = [];
    parseXml('<a>&#65;&amp;&lt;&#x42;&apos;</a>', { onText: (value) => text.push(value) }, 'part');
    expect(text.join('')).toBe("A&<B'");
  });

  it('rejects a DOCTYPE on a direct parse, whatever its casing', () => {
    expect(() => parseXml('<!DOCTYPE a><a/>', {}, 'part')).toThrow(WorkbookOpenError);
    expect(() => parseXml('<!doctype a><a/>', {}, 'part')).toThrow(WorkbookOpenError);
  });
});
